    'rec_calming_breaths': { 'en': 'Calming Breaths', 'hi': 'शांत श्वास', 'hn': 'Calming Breaths' },
    'rec_calming_breaths_desc': { 'en': 'Try a breathing exercise to quickly lower your heart rate.', 'hi': 'अपनी हृदय गति को तुरंत कम करने के लिए श्वास व्यायाम का प्रयास करें।', 'hn': 'Heart rate kam karne ke lie breathing exercise try karein.' },
    'rec_daily_affirmations': { 'en': 'Daily Affirmations', 'hi': 'दैनिक सकारात्मक विचार', 'hn': 'Daily Affirmations' },
    'rec_daily_affirmations_desc': { 'en': 'Remind yourself of your worth with some positive affirmations.', 'hi': 'कुछ सकारात्मक विचारों के साथ स्वयं को अपने महत्व की याद दिलाएँ।', 'hn': 'Positive affirmations padhein aur apne aapko behtar feel karwayein.' },
    'rec_release_energy': { 'en': 'Release Energy', 'hi': 'ऊर्जा मुक्त करें', 'hn': 'Release Energy' },
    'rec_release_energy_desc': { 'en': 'Channel your frustration into a physical grounding exercise.', 'hi': 'अपनी निराशा को शारीरिक ग्राउंडिंग व्यायाम में बदलें।', 'hn': 'Apni frustration ko grounding exercise se release karein.' },
    'rec_deep_meditation': { 'en': 'Deep Meditation', 'hi': 'गहन ध्यान', 'hn': 'Deep Meditation' },
    'rec_deep_meditation_desc': { 'en': 'Enhance your mood with a guided mindfulness session.', 'hi': 'निर्देशित माइंडफुलनेस सत्र के साथ अपना मूड बेहतर बनाएं।', 'hn': 'Guided mindfulness ke zariye apna mood aur behtar banayein.' },
    'rec_peaceful_reading': { 'en': 'Peaceful Reading', 'hi': 'शांतिपूर्ण पठन', 'hn': 'Peaceful Reading' },
    'rec_peaceful_reading_desc': { 'en': 'Relax your mind with some mindful literature.', 'hi': 'कुछ माइंडफुल साहित्य के साथ अपने दिमाग को आराम दें।', 'hn': 'Mindful literature padh kar apne dimaag ko relax karein.' },
    'rec_daily_checklist': { 'en': 'Daily Checklist', 'hi': 'दैनिक चेकलिस्ट', 'hn': 'Daily Checklist' },
    'rec_daily_checklist_desc': { 'en': 'Build healthy habits to maintain your wellness.', 'hi': 'अपने स्वास्थ्य को बनाए रखने के लिए स्वस्थ आदतें बनाएं।', 'hn': 'Wellness maintain karne ke liye healthy habits build karein.' },
    'tap_to_start': { 'en': 'Tap to Start', 'hi': 'शुरू करने के लिए टैप करें', 'hn': 'Shuru karne ke liye tap karein' },
    'breathe_in': { 'en': 'Breathe In...', 'hi': 'सांस अंदर लें...', 'hn': 'Saans andar lein...' },
    'hold': { 'en': 'Hold...', 'hi': 'रोकें...', 'hn': 'Rokein...' },
    'breathe_out': { 'en': 'Breathe Out...', 'hi': 'सांस बाहर छोड़ें...', 'hn': 'Saans baahar chhodein...' },
    'start_breathing': { 'en': 'Start', 'hi': 'शुरू करें', 'hn': 'Start' },
    'stop': { 'en': 'Stop', 'hi': 'रुकें', 'hn': 'Stop' },
    'breathing_footer_instr': { 'en': 'Focus entirely on your breath. Let thoughts pass by like clouds in the sky.', 'hi': 'पूरी तरह से अपनी सांसों पर ध्यान केंद्रित करें। विचारों को आकाश में बादलों की तरह गुजरने दें।', 'hn': 'Apni saans par focus karein. Soch ko baadalon ki tarah aane aur jaane dein.' },
    'thought_challenging': { 'en': 'Thought Challenging', 'hi': 'विचारों को चुनौती देना', 'hn': 'Thought Challenging' },
    'thought_challenging_desc': { 'en': 'Learn to identify and challenge negative or irrational thoughts.', 'hi': 'नकारात्मक या तर्कहीन विचारों को पहचानने और चुनौती देने का तरीका जानें।', 'hn': 'Negative thoughts ko pehchan kar unhe challenge karna seekhein.' },
    'tc_long_desc': { 'en': 'Cognitive restructuring helps you break down and analyze negative thought patterns.', 'hi': 'संज्ञानात्मक पुनर्गठन आपको नकारात्मक विचार पैटर्न को तोड़ने और विश्लेषण करने में मदद करता है।', 'hn': 'Cognitive restructuring se aap negative sochon ko analyze aur change kar sakte hain.' },
    'tc_step_1': { 'en': 'Identify the negative thought.', 'hi': 'नकारात्मक विचार को पहचानें।', 'hn': 'Negative thought ko pehchaano.' },
    'tc_step_2': { 'en': 'Determine the emotion you are feeling.', 'hi': 'तय करें कि आप कौन सी भावना महसूस कर रहे हैं।', 'hn': 'Jis emotion ko feel kar rahe ho, use pehchaano.' },
    'tc_step_3': { 'en': 'Find the evidence supporting this thought.', 'hi': 'इस विचार का समर्थन करने वाले साक्ष्य खोजें।', 'hn': 'Is soch ko support karne wale saboot khojo.' },
    'tc_step_4': { 'en': 'Find the evidence AGAINST this thought.', 'hi': 'इस विचार के विरूद्ध साक्ष्य खोजें।', 'hn': 'Is soch ke khilaf kya saboot hain, unhe khojo.' },
    'tc_step_5': { 'en': 'Identify any cognitive distortions.', 'hi': 'किसी भी संज्ञानात्मक विकृतियों को पहचानें।', 'hn': 'Dimaag mein chal rahi galtiyo ko indentify karo.' },
    'tc_step_6': { 'en': 'Develop an alternative, balanced thought.', 'hi': 'एक वैकल्पिक, संतुलित विचार विकसित करें।', 'hn': 'Ek naya, balanced aur positive thought socho.' },
    'tc_step_7': { 'en': 'Re-rate your emotion intensity.', 'hi': 'अपनी भावना की तीव्रता को पुनः रेट करें।', 'hn': 'Ab apni feeling ko dobara rate karo.' },
    'behavioral_activation': { 'en': 'Behavioral Activation', 'hi': 'व्यवहार सक्रियण', 'hn': 'Behavioral Activation' },
    'behavioral_activation_desc': { 'en': 'Engage in activities to improve your mood and energy.', 'hi': 'अपने मूड और ऊर्जा को बेहतर बनाने के लिए गतिविधियों में संलग्न हों।', 'hn': 'Mood aur energy theek karne ke liye nayi activities try karo.' },
    'ba_long_desc': { 'en': 'Overcome depression and low energy by scheduling and completing rewarding activities.', 'hi': 'पुरस्कृत गतिविधियों को निर्धारित और पूरा करके अवसाद और कम ऊर्जा पर काबू पाएं।', 'hn': 'Achhi and rewarding activities schedule karke low energy aur sadness ko door karo.' },
    'ba_step_1': { 'en': 'Identify an activity you used to enjoy.', 'hi': 'उस गतिविधि को पहचानें जिसका आप आनंद लेते थे।', 'hn': 'Jo activity pehle pasand thi, uske bare me socho.' },
    'ba_step_2': { 'en': 'Rate your current mood (1-10).', 'hi': 'अपने वर्तमान मूड को रेट करें (1-10)।', 'hn': 'Abhi apna mood rate karo (1-10).' },
    'ba_step_3': { 'en': 'Schedule a specific time for the activity.', 'hi': 'गतिविधि के लिए एक विशिष्ट समय निर्धारित करें।', 'hn': 'Activity ke liye ek time set karo.' },
    'ba_step_4': { 'en': 'Commit to doing it for just 5 minutes.', 'hi': 'इसे सिर्फ 5 मिनट करने का संकल्प लें।', 'hn': 'Kam se kam 5 minute isko zaroor karne ka decide karo.' },
    'ba_step_5': { 'en': 'Perform the activity.', 'hi': 'गतिविधि निष्पादित करें।', 'hn': 'Activity actually perform karo.' },
    'ba_step_6': { 'en': 'Rate your mood again after the activity.', 'hi': 'गतिविधि के बाद अपने मूड को फिर से रेट करें।', 'hn': 'Activity ke baad apna mood wapas rate karo.' },
    'ba_step_7': { 'en': 'Notice any improvements in energy.', 'hi': 'ऊर्जा में किसी भी सुधार पर ध्यान दें।', 'hn': 'Check karo ki kya energy level badha hai.' },
    'exposure_therapy': { 'en': 'Fear Exposure', 'hi': 'भय का सामना', 'hn': 'Fear Exposure' },
    'exposure_therapy_desc': { 'en': 'Gradually face your fears in a safe, controlled manner.', 'hi': 'सुरक्षित, नियंत्रित तरीके से धीरे-धीरे अपने डर का सामना करें।', 'hn': 'Dheere dheere aisi baato ka samna karo jinse darr lagta hai.' },
    'et_long_desc': { 'en': 'Desensitize yourself to anxiety triggers through careful, graded exposure.', 'hi': 'सावधान, वर्गीकृत एक्सपोजर के माध्यम से खुद को चिंता ट्रिगर्स के प्रति असंवेदनशील बनाएं।', 'hn': 'Anxiety triggers ko aaram aaram se face karke unse darr kam karo.' },
    'et_step_1': { 'en': 'Create a list of anxiety triggers.', 'hi': 'चिंता ट्रिगर्स की एक सूची बनाएं।', 'hn': 'Jisse anxiety hoti hai unki list banao.' },
    'et_step_2': { 'en': 'Rank them from least to most scary (1-100).', 'hi': 'उन्हें कम से कम सबसे डरावने (1-100) के क्रम में रखें।', 'hn': 'Kam darr waale se start karke sabse zyada darr waale tak rank karo (1-100).' },
    'et_step_3': { 'en': 'Select the least scary item to start.', 'hi': 'शुरू करने के लिए सबसे कम डरावना विषय चुनें।', 'hn': 'Sabse kam darr waali cheez choose karo.' },
    'et_step_4': { 'en': 'Plan a safe exposure event.', 'hi': 'एक सुरक्षित एक्सपोजर इवेंट की योजना बनाएं।', 'hn': 'Use safe tarike se face karne ka plan banao.' },
    'et_step_5': { 'en': 'Engage with the trigger.', 'hi': 'ट्रिगर के साथ संलग्न हों।', 'hn': 'Us trigger ko face karo.' },
    'et_step_6': { 'en': 'Stay with the anxiety until it peaks and drops.', 'hi': 'चिंता के साथ तब तक रहें जब तक कि वह चरम पर पहुंचकर कम न हो जाए।', 'hn': 'Jab tak anxiety badh ke kam na ho jaye, tab tak ruke raho.' },
    'et_step_7': { 'en': 'Breathe deeply to regulate your nervous system.', 'hi': 'अपने तंत्रिका तंत्र को नियंत्रित करने के लिए गहरी सांस लें।', 'hn': 'Gehri saans lo taaki body relax hoye.' },
    'et_step_8': { 'en': 'Reflect on your success and move to the next item.', 'hi': 'अपनी सफलता पर विचार करें और अगली वस्तु पर जाएं।', 'hn': 'Apni jeet par focus karo aur next task ke baare me socho.' },
    'cognitive_restructuring': { 'en': 'Cognitive Restructuring', 'hi': 'संज्ञानात्मक पुनर्गठन', 'hn': 'Cognitive Restructuring' },
    'cognitive_restructuring_desc': { 'en': 'Transform deeply held core beliefs and rules.', 'hi': 'गहराई से जुड़ी मुख्य मान्यताओं और नियमों को बदलें।', 'hn': 'Apni purani negative sochon aur rules ko badlo.' },
    'cr_long_desc': { 'en': 'Identify unhelpful core beliefs and replace them with empowering alternatives.', 'hi': 'अनुपयोगी मुख्य मान्यताओं को पहचानें और उन्हें सशक्त विकल्पों से बदलें।', 'hn': 'Aise core beliefs pehchaano jo faydemand nahi hain, aur unhe theek alternatives se replace karo.' },
    'cr_step_1': { 'en': 'Identify a recurring negative pattern.', 'hi': 'बार-बार होने वाले नकारात्मक पैटर्न को पहचानें।', 'hn': 'Koi aisi negative aadat ya soch batao jo baar baar aati ho.' },
    'cr_step_2': { 'en': 'Ask "What does this mean about me?"', 'hi': 'पूछें "मेरे बारे में इसका क्या मतलब है?"', 'hn': 'Socho "Iska mere baare mein kya matlab nikalta hai?"' },
    'cr_step_3': { 'en': 'Uncover the underlying core belief.', 'hi': 'अंतर्निहित मूल धारणा को उजागर करें।', 'hn': 'Asli reason ya core belief ko bahar nikalo.' },
