  static String get(String key, String lang, [Object? val]) {
    String text = translations[key]?[lang] ?? translations[key]?['en'] ?? key;
    if (val != null) {
      if (val is Map) {
        val.forEach((k, v) {
          text = text.replaceAll('{$k}', v.toString());
        });
      } else {
        text = text.replaceAll('{val}', val.toString());
      }
    }
    return text;
  }

  /// Localize a mood name by looking up 'mood_<lowercase>' or '<lowercase>' key.
  static String localizeMood(String mood, String lang) {
    final lower = mood.toLowerCase().replaceAll(' ', '_');
    // Try mood-specific key first, then bare key, then capitalize original
    return translations['mood_$lower']?[lang]
        ?? translations[lower]?[lang]
        ?? translations['mood_$lower']?['en']
        ?? mood;
  }
